/** Polls a condition for up to half a second, so a teardown waits for a socket to be seen closed. */
export const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

/** Closes a suite's own clients, then each server once it has seen its sockets close, so no close is logged late. */
export async function closeEngines(
  hals: Array<{wss: {clients: {size: number}}; stop: () => Promise<void>}>,
  sockets: WebSocket[]
): Promise<void> {
  for (const client of sockets.splice(0)) client.terminate();
  for (const hal of hals.splice(0)) {
    await eventually(() => hal.wss.clients.size === 0);
    await hal.stop();
  }
}

/** A store with only the required members, so an optional one can be added, replaced or left out per test. */
